"""Sort semantic version strings by SemVer 2.0.0 precedence."""


def _parse(version):
    """Return a sort key for a SemVer string. Build metadata is ignored."""
    core = version.split('+', 1)[0]
    if '-' in core:
        base, pre = core.split('-', 1)
        pre_ids = pre.split('.')
    else:
        base, pre_ids = core, None

    major, minor, patch = (int(part) for part in base.split('.'))

    if pre_ids is None:
        # A release version has higher precedence than any pre-release of it.
        pre_key = (1, ())
    else:
        idents = []
        for ident in pre_ids:
            if ident.isdigit():
                # Numeric identifiers compare as integers and sort below alphanumeric ones.
                idents.append((0, int(ident), ''))
            else:
                # Alphanumeric identifiers compare in ASCII order.
                idents.append((1, 0, ident))
        # Tuple comparison makes a shorter list lower when the shared prefix is equal.
        pre_key = (0, tuple(idents))

    return (major, minor, patch, pre_key)


def sort_versions(vs):
    """Return the version strings sorted lowest precedence first.

    Python's sort is stable, so versions that tie keep their input order.
    """
    return sorted(vs, key=_parse)
